// Fails if app code uses physical-direction Tailwind classes (ml-, pr-, left-, text-right, ...).
// Use logical ones instead: ms/me, ps/pe, start/end, text-start/text-end, border-s/e, rounded-s/e.
// src/components/ui is generated by the shadcn CLI (with rtl: true) and is skipped.
import { readdirSync, readFileSync, statSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../src')
const skip = path.join(root, 'components', 'ui')
const PHYSICAL =
  /(?<![\w-])(?:-?(?:m|p|scroll-m|scroll-p)[lr]-|-?(?:left|right)-|text-(?:left|right)\b|border-[lr](?:-|\b)|rounded-(?:[tb])?[lr](?:-|\b)|float-(?:left|right)\b|clear-(?:left|right)\b)/

const problems = []
function walk(dir) {
  for (const name of readdirSync(dir)) {
    const full = path.join(dir, name)
    if (full === skip) continue
    if (statSync(full).isDirectory()) walk(full)
    else if (/\.(tsx?|jsx?)$/.test(name)) {
      readFileSync(full, 'utf8')
        .split('\n')
        .forEach((line, i) => {
          for (const m of line.matchAll(/className=(?:"([^"]*)"|\{`([^`]*)`\}|'([^']*)')/g)) {
            const classes = (m[1] ?? m[2] ?? m[3]).split(/\s+/)
            for (const cls of classes) {
              const bare = cls.split(':').pop()
              if (PHYSICAL.test(bare)) problems.push(`${path.relative(root, full)}:${i + 1}: ${cls}`)
            }
          }
        })
    }
  }
}
walk(root)
if (problems.length) {
  console.error('Physical-direction classes found (use logical ones):\n' + problems.join('\n'))
  process.exit(1)
}
